SET @event_engine := (SELECT COUNT(*)=1 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND table_type='BASE TABLE' AND engine='InnoDB');
SET @event_indexes := (SELECT COUNT(*)=3 FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' GROUP BY index_name) x WHERE (index_name='PRIMARY' AND cols='supplementary_exam_registration_event_id') OR cols IN ('supplementary_exam_registration_id,created_at','actor_user_id'));
SET @event_fks := (SELECT COUNT(*)=2 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND referenced_table_schema='alrowad_uni_rust' AND ((column_name='supplementary_exam_registration_id' AND referenced_table_name='supplementary_exam_registrations' AND referenced_column_name='supplementary_exam_registration_id') OR (column_name='actor_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id')));
SET @event_signedness := (SELECT COUNT(*)=2 FROM information_schema.key_column_usage k JOIN information_schema.columns c ON c.table_schema=k.table_schema AND c.table_name=k.table_name AND c.column_name=k.column_name JOIN information_schema.columns p ON p.table_schema=k.referenced_table_schema AND p.table_name=k.referenced_table_name AND p.column_name=k.referenced_column_name WHERE k.table_schema='alrowad_uni_rust' AND k.table_name='supplementary_exam_registration_events' AND c.column_type=p.column_type);
SET @event_state := IF(@event_exists=0,'ABSENT',IF(@event_engine AND @event_columns AND @event_indexes AND @event_fks AND @event_signedness,'COMPATIBLE','CONFLICT'));
SET @permission_collision := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p LEFT JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code IN ('supplementary_exams.registrations.view','supplementary_exams.registrations.self','supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND (p.is_active<>1 OR m.module_code<>'exams' OR m.is_active<>1));
SET @permission_duplicates := (SELECT COUNT(*) FROM (SELECT permission_code FROM `alrowad_uni_rust`.`permissions` WHERE permission_code IN ('supplementary_exams.registrations.view','supplementary_exams.registrations.self','supplementary_exams.registrations.manage','supplementary_exams.registrations.window') GROUP BY permission_code HAVING COUNT(*)>1) d);
SET @off_matrix := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (p.permission_code='supplementary_exams.registrations.self' AND r.role_code<>'student') OR (p.permission_code IN ('supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND r.role_code<>'registration_officer') OR (p.permission_code='supplementary_exams.registrations.view' AND r.role_code NOT IN ('registration_officer','exam_officer','dean','vice_president_scientific')));
SET @rbac_safe := @permission_collision=0 AND @permission_duplicates=0 AND @off_matrix=0 AND (SELECT COUNT(*)=5 FROM `alrowad_uni_rust`.`roles` WHERE role_code IN ('student','registration_officer','exam_officer','dean','vice_president_scientific') AND is_active=1) AND (SELECT COUNT(*)=1 FROM `alrowad_uni_rust`.`system_modules` WHERE module_code='exams' AND is_active=1);
SET @apply_ready := @phase3_ready AND @period_lifecycle_width_ready AND @reg_state<>'CONFLICT' AND @event_state<>'CONFLICT' AND @rbac_safe;
SET @sql := IF(@apply_ready AND @reg_state='ABSENT',"CREATE TABLE `alrowad_uni_rust`.`supplementary_exam_registrations` (`supplementary_exam_registration_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_offering_id` INT NOT NULL,`student_id` INT NOT NULL,`student_course_registration_id` INT NOT NULL,`status` VARCHAR(16) NOT NULL,`current_slot` TINYINT NULL,`eligibility_reason` VARCHAR(40) NOT NULL,`registration_channel` VARCHAR(24) NOT NULL,`registered_by_user_id` INT NOT NULL,`registered_at` DATETIME NOT NULL,`cancelled_by_user_id` INT NULL,`cancelled_at` DATETIME NULL,`cancellation_reason` TEXT NULL,`eligibility_checked_at` DATETIME NOT NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`supplementary_exam_registration_id`),UNIQUE KEY `uq_ser_source` (`supplementary_exam_offering_id`,`student_course_registration_id`),UNIQUE KEY `uq_ser_current` (`supplementary_exam_offering_id`,`student_id`,`current_slot`),KEY `ix_ser_student_current` (`student_id`,`current_slot`),KEY `ix_ser_offering_status` (`supplementary_exam_offering_id`,`status`),KEY `ix_ser_registered_by` (`registered_by_user_id`),KEY `ix_ser_cancelled_by` (`cancelled_by_user_id`),CONSTRAINT `fk_ser_offering` FOREIGN KEY (`supplementary_exam_offering_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_offerings` (`supplementary_exam_offering_id`),CONSTRAINT `fk_ser_student` FOREIGN KEY (`student_id`) REFERENCES `alrowad_uni_rust`.`students` (`student_id`),CONSTRAINT `fk_ser_source` FOREIGN KEY (`student_course_registration_id`) REFERENCES `alrowad_uni_rust`.`student_course_registrations` (`student_course_registration_id`),CONSTRAINT `fk_ser_registered_by` FOREIGN KEY (`registered_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`),CONSTRAINT `fk_ser_cancelled_by` FOREIGN KEY (`cancelled_by_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT='[phase4-supplementary-exam-registration] official list'","SELECT 'REGISTRATIONS_NOT_CREATED'");PREPARE ddl FROM @sql;EXECUTE ddl;DEALLOCATE PREPARE ddl;
SET @post_reg_ready := (SELECT COUNT(*)=1 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' AND table_type='BASE TABLE' AND engine='InnoDB') AND (SELECT COUNT(*)=16 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations') AND (SELECT COUNT(*)=7 FROM (SELECT non_unique,index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' GROUP BY index_name,non_unique) x WHERE (index_name='PRIMARY' AND cols='supplementary_exam_registration_id') OR (non_unique=0 AND cols IN ('supplementary_exam_offering_id,student_course_registration_id','supplementary_exam_offering_id,student_id,current_slot')) OR cols IN ('student_id,current_slot','supplementary_exam_offering_id,status','registered_by_user_id','cancelled_by_user_id')) AND (SELECT COUNT(*)=5 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registrations' AND referenced_table_schema='alrowad_uni_rust');
SET @sql := IF(@apply_ready AND @post_reg_ready AND @event_state='ABSENT',"CREATE TABLE `alrowad_uni_rust`.`supplementary_exam_registration_events` (`supplementary_exam_registration_event_id` INT NOT NULL AUTO_INCREMENT,`supplementary_exam_registration_id` INT NOT NULL,`event_type` VARCHAR(24) NOT NULL,`from_status` VARCHAR(16) NULL,`to_status` VARCHAR(16) NOT NULL,`actor_user_id` INT NOT NULL,`notes` TEXT NULL,`created_at` DATETIME NOT NULL,PRIMARY KEY (`supplementary_exam_registration_event_id`),KEY `ix_sere_history` (`supplementary_exam_registration_id`,`created_at`),KEY `ix_sere_actor` (`actor_user_id`),CONSTRAINT `fk_sere_registration` FOREIGN KEY (`supplementary_exam_registration_id`) REFERENCES `alrowad_uni_rust`.`supplementary_exam_registrations` (`supplementary_exam_registration_id`),CONSTRAINT `fk_sere_actor` FOREIGN KEY (`actor_user_id`) REFERENCES `alrowad_uni_rust`.`users` (`user_id`)) ENGINE=InnoDB COMMENT='[phase4-supplementary-exam-registration] immutable events'","SELECT 'EVENTS_NOT_CREATED'");PREPARE ddl FROM @sql;EXECUTE ddl;DEALLOCATE PREPARE ddl;
SET @post_event_ready := (SELECT COUNT(*)=1 FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND table_type='BASE TABLE' AND engine='InnoDB') AND (SELECT COUNT(*)=8 FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events') AND (SELECT COUNT(*)=3 FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' GROUP BY index_name) x WHERE (index_name='PRIMARY' AND cols='supplementary_exam_registration_event_id') OR cols IN ('supplementary_exam_registration_id,created_at','actor_user_id')) AND (SELECT COUNT(*)=2 FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_registration_events' AND referenced_table_schema='alrowad_uni_rust');
START TRANSACTION;
INSERT INTO `alrowad_uni_rust`.`permissions` (module_id,permission_code,permission_name,description,is_active,created_at,updated_at) SELECT m.module_id,x.code,x.name,'[phase4-supplementary-exam-registration]',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`system_modules` m JOIN (SELECT 'supplementary_exams.registrations.view' code,'View supplementary registrations' name UNION ALL SELECT 'supplementary_exams.registrations.self','Self supplementary registration' UNION ALL SELECT 'supplementary_exams.registrations.manage','Manage supplementary registrations' UNION ALL SELECT 'supplementary_exams.registrations.window','Manage supplementary registration window') x WHERE @apply_ready AND @post_reg_ready AND @post_event_ready AND m.module_code='exams' AND m.is_active=1 AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`permissions` p WHERE p.permission_code=x.code);
INSERT INTO `alrowad_uni_rust`.`role_permissions` (role_id,permission_id,granted_at) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON (p.permission_code='supplementary_exams.registrations.self' AND r.role_code='student') OR (p.permission_code='supplementary_exams.registrations.view' AND r.role_code IN ('registration_officer','exam_officer','dean','vice_president_scientific')) OR (p.permission_code IN ('supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND r.role_code='registration_officer') WHERE @apply_ready AND @post_reg_ready AND @post_event_ready AND r.is_active=1 AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`role_permissions` rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id);COMMIT;
SET @post_permissions := (SELECT COUNT(DISTINCT p.permission_code)=4 FROM `alrowad_uni_rust`.`permissions` p JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code IN ('supplementary_exams.registrations.view','supplementary_exams.registrations.self','supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND p.is_active=1 AND m.module_code='exams' AND m.is_active=1);
SET @post_mappings := (SELECT COUNT(DISTINCT CONCAT(r.role_code,':',p.permission_code))=7 FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (p.permission_code='supplementary_exams.registrations.self' AND r.role_code='student') OR (p.permission_code='supplementary_exams.registrations.view' AND r.role_code IN ('registration_officer','exam_officer','dean','vice_president_scientific')) OR (p.permission_code IN ('supplementary_exams.registrations.manage','supplementary_exams.registrations.window') AND r.role_code='registration_officer'));
SET @applied := @apply_ready AND @post_reg_ready AND @post_event_ready AND @post_permissions AND @post_mappings;
SELECT 'APPLY_RESULT' AS report_section,IF(@applied,'APPLIED','BLOCKED') AS result,IF(NOT @phase3_ready,'PHASE3_NOT_DEPLOYED',IF(NOT @period_lifecycle_width_ready,'PERIOD_LIFECYCLE_SCHEMA_TOO_NARROW',IF(@reg_state='CONFLICT' OR @event_state='CONFLICT','TARGET_SCHEMA_CONFLICT',IF(NOT @rbac_safe,'RBAC_CONFLICT',NULL)))) AS blocker_code,@reg_state AS initial_registrations_state,@event_state AS initial_events_state;
